import 'package:path/path.dart'; import 'package:sqflite/sqflite.dart'; import '../models/expense.dart'; import '../models/recurring_bill.dart';
class DatabaseService { DatabaseService._(); static final instance=DatabaseService._(); late Database db;
 Future<void> init() async { db=await openDatabase(join(await getDatabasesPath(),'salary_manager.db'),version:1,onCreate:(d,v) async { await d.execute('CREATE TABLE expenses(id INTEGER PRIMARY KEY AUTOINCREMENT, amount REAL, category TEXT, date TEXT, note TEXT)'); await d.execute('CREATE TABLE bills(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, amount REAL, category TEXT, dueDay INTEGER, reminderDays INTEGER)'); }); }
 Future<int> addExpense(Expense e)=>db.insert('expenses',e.toMap()); Future<List<Expense>> monthExpenses(DateTime d) async { final rows=await db.query('expenses',where:'date >= ? AND date < ?',whereArgs:[DateTime(d.year,d.month).toIso8601String(),DateTime(d.year,d.month+1).toIso8601String()],orderBy:'date DESC'); return rows.map(Expense.fromMap).toList(); } Future<void> deleteExpense(int id)=>db.delete('expenses',where:'id=?',whereArgs:[id]); Future<int> addBill(RecurringBill b)=>db.insert('bills',b.toMap()); Future<List<RecurringBill>> bills() async=>(await db.query('bills',orderBy:'dueDay')).map(RecurringBill.fromMap).toList(); }
